USE thriftedgh;

-- Foose Plug
SET @u = (SELECT user_id FROM users WHERE email = 'fooseplug@demo.com');
UPDATE seller_applications SET business_details = 'Y2K and vintage bags, hats, rings and sunglasses with attitude.', status = 'approved' WHERE user_id = @u;
SET @s = (SELECT seller_id FROM seller_profiles WHERE user_id = @u);
UPDATE products SET status = 'hidden' WHERE seller_id = @s AND status = 'available';

